import{_ as i}from"./chunks/interactive-mode.GWxR--kb.js";import{_ as s,o as t,c as e,a2 as p}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"zh/quickstart.md","filePath":"zh/quickstart.md"}'),n={name:"zh/quickstart.md"};function h(l,a,d,o,r,c){return t(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>Pi 在终端中运行，操作你机器上的文件。使用它需要通过受支持的提供商（provider）访问模型，可以是订阅、API key 或本地模型。</p><p>Windows 原生安装请阅读 <a href="./windows.html">Windows 安装</a>。Android 请阅读 <a href="./termux.html">Termux 安装</a>。</p><h2 id="_1-安装-pi" tabindex="-1">1. 安装 Pi <a class="header-anchor" href="#_1-安装-pi" aria-label="Permalink to &quot;1. 安装 Pi&quot;">​</a></h2><p>在 macOS 或 Linux 上，可以使用安装脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pi.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>安装脚本会锁定所有依赖，并通过 <code>pi update</code> 更新 Pi。也可以从 npm 安装 Pi，这种方式不锁定传递依赖。需要 Node.js 22.19 或更新版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @earendil-works/pi-coding-agent</span></span></code></pre></div><p>正常的 npm 安装不需要运行依赖的生命周期脚本。</p><p>在 macOS 或 Linux 上使用 Nix 时，可从 Pi 的 flake 安装最新版本。Nix 从源码构建 Pi：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github:earendil-works/pi/stable</span></span></code></pre></div><p>较旧的 Nix 版本使用 <code>nix profile install</code>。更新使用 <code>nix profile upgrade pi</code>；<code>pi update</code> 无法更新 Nix 安装。要固定版本，使用标签，如 <code>github:earendil-works/pi/v1.0.0</code>。</p><p>验证安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="_2-启动-pi" tabindex="-1">2. 启动 Pi <a class="header-anchor" href="#_2-启动-pi" aria-label="Permalink to &quot;2. 启动 Pi&quot;">​</a></h2><p>切换到你想让 Pi 处理的文件夹，然后启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span></span></code></pre></div><p>工作文件夹帮助 Pi 发现相关文件、指令和配置。Pi 也用它对已保存的会话（session）分组。</p><p align="center"><img src="`+i+'" alt="Pi running in a terminal with a conversation, input editor, and status footer" width="750"></p><p>界面显示你的对话、用于输入提示词和命令的编辑器，以及包含当前文件夹、模型和会话状态的底部栏。学习添加文件、运行命令、指导进行中的工作和管理结果，参见 <a href="./usage.html">在终端中使用 Pi</a>。</p><p><a id="3-choose-a-model"></a></p><h2 id="_3-选择模型" tabindex="-1">3. 选择模型 <a class="header-anchor" href="#_3-选择模型" aria-label="Permalink to &quot;3. 选择模型&quot;">​</a></h2><p><strong>模型（model）</strong> 生成 Pi 的响应。<strong>提供商（provider）</strong> 是 Pi 用来访问该模型的服务或账户。</p><p>在 Pi 中运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login</span></span></code></pre></div><p>选择提供商，然后按提示使用订阅或存储 API key。之后如果想选择其他可用模型，运行 <code>/model</code>。</p><p>受支持的提供商、环境变量认证、本地模型和自定义端点参见 <a href="./models.html">选择模型和提供商</a>。</p><h2 id="_4-给-pi-一项任务" tabindex="-1">4. 给 Pi 一项任务 <a class="header-anchor" href="#_4-给-pi-一项任务" aria-label="Permalink to &quot;4. 给 Pi 一项任务&quot;">​</a></h2><p>Pi 会展示它执行的每次文件读取、搜索、命令和编辑。它不会在每次工具调用前询问。</p><p>输入一项符合你工作的任务，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Summarize @meeting-notes.md and save the action items to action-items.md.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain how this repository is structured and how to run its checks.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Compare @previous.csv with @current.csv and summarize the important changes.</span></span></code></pre></div><p>在编辑器中输入 <code>@</code> 可搜索文件，而无需输入完整路径。Pi 完成后，检查其响应和被更改的文件。重要工作请使用版本控制或备份。对于不受信任或无人值守的工作，请使用容器或其他沙箱。参见 <a href="./security.html">安全</a>。</p><h2 id="稍后继续" tabindex="-1">稍后继续 <a class="header-anchor" href="#稍后继续" aria-label="Permalink to &quot;稍后继续&quot;">​</a></h2><p>Pi 会自动保存会话。退出 Pi 后，用以下命令恢复同一工作文件夹最近一次的会话：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span></code></pre></div><p>使用 <code>/resume</code> 选择其他已保存的会话。会话命名、分支（branch）、压缩（compaction）、导出和共享参见 <a href="./sessions.html">继续或分支会话</a>。</p><h2 id="后续步骤" tabindex="-1">后续步骤 <a class="header-anchor" href="#后续步骤" aria-label="Permalink to &quot;后续步骤&quot;">​</a></h2><ul><li><a href="./usage.html">交互式使用 Pi</a>，学习输入、命令、快捷键和排队消息。</li><li><a href="./configuration.html#context-files">添加指令</a>，让 Pi 在某个文件夹中工作时始终遵循。</li><li><a href="./models.html">选择模型和提供商</a>。</li></ul><p><a id="choose-how-to-customize-pi"></a></p><h3 id="选择定制方式" tabindex="-1">选择定制方式 <a class="header-anchor" href="#选择定制方式" aria-label="Permalink to &quot;选择定制方式&quot;">​</a></h3><p>从满足需求的最简单机制开始：</p><table tabindex="0"><thead><tr><th>需求</th><th>起步方式</th></tr></thead><tbody><tr><td>为某个文件夹给 Pi 持久指令</td><td><a href="./configuration.html#context-files"><code>AGENTS.md</code></a></td></tr><tr><td>从 <code>/</code> 菜单复用提示词</td><td><a href="./prompt-templates.html">提示词模板</a></td></tr><tr><td>添加任务专属指令和配套文件</td><td><a href="./skills.html">技能</a></td></tr><tr><td>添加可执行工具、命令或事件处理器</td><td><a href="./extensions.html">扩展</a></td></tr><tr><td>构建自定义终端组件</td><td><a href="./tui.html">终端 UI</a></td></tr><tr><td>接入不受支持的模型服务</td><td><a href="./custom-provider.html">自定义提供商</a></td></tr><tr><td>安装或分发多个资源</td><td><a href="./packages.html">Pi 包</a></td></tr></tbody></table><h2 id="卸载-pi" tabindex="-1">卸载 Pi <a class="header-anchor" href="#卸载-pi" aria-label="Permalink to &quot;卸载 Pi&quot;">​</a></h2><p>如果用 npm 安装了 Pi，运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @earendil-works/pi-coding-agent</span></span></code></pre></div><p>如果使用安装脚本，重新运行它并选择 <strong>Uninstall Pi</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pi.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>如果用 Nix 安装了 Pi，运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pi</span></span></code></pre></div><p>以上方式都不会从 <code>~/.pi/agent/</code> 移除配置、凭据、会话或已安装的 Pi 包。</p>',52)])])}const b=s(n,[["render",h]]);export{u as __pageData,b as default};
